import sys
input = sys.stdin.read
data = input().split()

D = int(data[0])
G = int(data[1])

problems = []
for i in range(D):
    p = int(data[2 * i + 2])
    c = int(data[2 * i + 3])
    problems.append((p, c))

dp = [float('inf')] * (G + 1)
dp[0] = 0

for p, c in problems:
    for j in range(G, -1, -1):
        for k in range(p + 1):
            if j >= k * 100:
                dp[j] = min(dp[j], dp[j - k * 100] + k + (c if k == p else 0))

min_problems = float('inf')
for j in range(G, -1, -1):
    if dp[j] != float('inf'):
        min_problems = min(min_problems, dp[j])
        break

print(min_problems)
